32:   constructor(physics: PhysicsWorld, spawn: Vec3, options: GolfBallPhysicsOptions = {}) {
33:     const config = GAME_CONFIG.physics;
34:     const radius = options.radius ?? config.ballRadius;
35:     const mass = options.mass ?? config.ballMass;
36:     this.rollingResistance = options.rollingResistance ?? 0.32;
37:     this.airResistance = options.airResistance ?? 0.018;
38:     this.body = physics.world.createRigidBody(
39:       RAPIER.RigidBodyDesc.dynamic()
40:         .setTranslation(spawn.x, spawn.y, spawn.z)
41:         .setLinearDamping(options.linearDamping ?? 0.08)
42:         .setAngularDamping(options.angularDamping ?? 0.22)
43:         .setCcdEnabled(true),
44:     );
45:     this.collider = physics.world.createCollider(
46:       RAPIER.ColliderDesc.ball(radius)
47:         .setMass(mass)
48:         .setFriction(options.friction ?? 0.55)
49:         .setRestitution(options.restitution ?? 0.32)
50:         .setCollisionGroups(BALL_COLLISION_GROUPS),
51:       this.body,
52:     );
53:     this.lastSafePosition = { ...spawn };
54:   }
55: 
56:   get position(): Vec3 {
57:     const p = this.body.translation();
58:     return { x: p.x, y: p.y, z: p.z };
59:   }
60: 
61:   get velocity(): Vec3 {
62:     const v = this.body.linvel();
63:     return { x: v.x, y: v.y, z: v.z };
64:   }
65: 
66:   get speed(): number {
67:     return magnitude(this.velocity);
68:   }
69: 
70:   get canShoot(): boolean {
71:     return this.body.isSleeping() || this.speed <= GAME_CONFIG.physics.ballStopThreshold;
72:   }
