1: import type { Vec3 } from '../contracts/math';
2: 
3: export function clamp(value: number, min: number, max: number): number {
4:   return Math.min(max, Math.max(min, value));
5: }
6: 
7: export function magnitude(v: Vec3): number {
8:   return Math.hypot(v.x, v.y, v.z);
9: }
10: 
11: export function normalizeHorizontal(direction: Vec3): Vec3 | null {
12:   const length = Math.hypot(direction.x, direction.z);
13:   if (length < 1e-8) return null;
14:   return { x: direction.x / length, y: 0, z: direction.z / length };
15: }
16: 
17: export function shotImpulseFromCharge(
18:   charge: number,
19:   minPower: number,
20:   maxPower: number,
21:   exponent: number,
22: ): number {
23:   const t = clamp(charge, 0, 1);
24:   return minPower + (maxPower - minPower) * Math.pow(t, exponent);
25: }
26: 
27: export function cappedVelocity(v: Vec3, maxSpeed: number): Vec3 {
28:   const speed = magnitude(v);
29:   if (speed <= maxSpeed || speed < 1e-8) return { ...v };
30:   const scale = maxSpeed / speed;
31:   return { x: v.x * scale, y: v.y * scale, z: v.z * scale };
32: }
33: 
34: export function shouldSleep(speed: number, stopThreshold: number, quietSeconds: number, sleepDelaySeconds: number): boolean {
35:   return speed <= stopThreshold && quietSeconds >= sleepDelaySeconds;
36: }
